{
  "$schema": "https://json.schemastore.org/package.json",
  "name": "opencode-recap",
  "version": "0.1.1",
  "description": "OpenCode TUI plugin: an AI session recap that renders in the sidebar",
  "type": "module",
  "license": "MIT",
  "author": "Jim Merioles",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/jimmerioles/opencode-recap.git"
  },
  "homepage": "https://github.com/jimmerioles/opencode-recap#readme",
  "bugs": {
    "url": "https://github.com/jimmerioles/opencode-recap/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "opencode-tui",
    "ai",
    "llm",
    "ai-agents",
    "coding-agents",
    "recap",
    "summary",
    "summarization",
    "context-management",
    "tui",
    "terminal",
    "developer-tools",
    "solidjs"
  ],
  "exports": {
    ".": "./index.ts",
    "./tui": "./tui.tsx"
  },
  "files": [
    "index.ts",
    "tui.tsx",
    "README.md",
    "LICENSE"
  ],
  "engines": {
    "opencode": ">=2.0.0"
  },
  "scripts": {
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "@opencode/plugin": "^2.1.2"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.5.17",
    "@opentui/solid": ">=0.5.17",
    "solid-js": ">=1.9.0"
  },
  "devDependencies": {
    "@opencode/theme": "^2.1.2",
    "@opentui/core": "^0.6.6",
    "@opentui/solid": "^0.6.6",
    "solid-js": "1.9.12",
    "typescript": "^5.8.2"
  }
}
